import { content as c } from './content.js';
const $ = s => document.querySelector(s);
const escape = s => String(s).replace(/[&<>"']/g, x => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const safeUrl = url => { try { const u = new URL(url, location.href); return ['https:','http:'].includes(u.protocol) ? u.href : null; } catch { return null; } };
const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
$('.hero-brief').textContent=c.brief;
$('.cv-link').href=c.cv;
document.querySelectorAll('.email-link').forEach(a=>a.href=`mailto:${c.email}`);
$('.email-text').textContent=c.email;$('.whatsapp-link').href=c.whatsapp;$('#year').textContent=new Date().getFullYear();
$('#skills').innerHTML=c.skills.map(s=>`<article class="skill reveal"><span class="skill-icon">${escape(s.icon)}</span><h3>${escape(s.name)}</h3><p>${escape(s.detail)}</p><details><summary>Explore skills</summary><ul>${s.terms.map(t=>`<li>${escape(t)}</li>`).join('')}</ul></details></article>`).join('');
$('#project-cards').innerHTML=c.projects.map(p=>`<article class="swiper-slide project-card"><div class="project-top"><span>${p.number}</span><small>${escape(p.category)}</small></div><div class="project-visual ${p.visual}" role="img" aria-label="Illustrative graphic for ${escape(p.title)}, not a project screenshot">${[45,68,42,87,60,100].map(h=>`<i style="height:${h}%"></i>`).join('')}</div><h3>${escape(p.title)}</h3><p>${escape(p.problem)}</p><p class="outcome">${escape(p.outcome)}</p><div class="tags">${p.stack.map(t=>`<span>${escape(t)}</span>`).join('')}</div>${p.url&&safeUrl(p.url)?`<a class="text-link" href="${escape(safeUrl(p.url))}" target="_blank" rel="noopener">View project ↗</a>`:'<span class="pending">Completed project · link to be added</span>'}</article>`).join('');
$('#timeline').innerHTML=c.journey.map((j,i)=>`<article class="chapter" data-step="${i}"><div class="chapter-meta"><span>0${i+1}</span><span>${escape(j.status)}</span></div><h3>${escape(j.title)}</h3><p>${escape(j.text)}</p></article>`).join('');
$('#learning-log').innerHTML=c.log.map(l=>`<article class="log-entry"><time datetime="${escape(l.date)}">${new Date(l.date+'T12:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})}</time><div><h3>${escape(l.title)}</h3><p>${escape(l.text)}</p></div></article>`).join('');
$('#media-tools').innerHTML=c.mediaTools.map((t,i)=>`<div class="tool reveal"><b aria-hidden="true">${['Pr','Ae','Ps','Lr'][i]||t.slice(0,2)}</b>${escape(t)}</div>`).join('');
// Embed only supported video hosts; other supplied URLs become ordinary links.
function filmMedia(f,i){const url=f.url&&safeUrl(f.url);if(url){const u=new URL(url);let embed='';if(u.hostname==='youtu.be')embed='https://www.youtube-nocookie.com/embed/'+encodeURIComponent(u.pathname.slice(1));if(['www.youtube.com','youtube.com'].includes(u.hostname)&&u.searchParams.get('v'))embed='https://www.youtube-nocookie.com/embed/'+encodeURIComponent(u.searchParams.get('v'));if(['vimeo.com','www.vimeo.com'].includes(u.hostname)&&/^\/\d+$/.test(u.pathname))embed='https://player.vimeo.com/video'+u.pathname;if(embed)return `<iframe src="${escape(embed)}" title="${escape(f.title)}" loading="lazy" allow="fullscreen; picture-in-picture" allowfullscreen></iframe>`;if(/\.(mp4|webm)$/i.test(u.pathname))return `<video controls preload="none" src="${escape(url)}" aria-label="${escape(f.title)}"></video>`;return `<a class="film-art" href="${escape(url)}" target="_blank" rel="noopener"><strong>WATCH ↗</strong></a>`;}return `<div class="film-art"><span>DEMO / NOT PORTFOLIO WORK</span><strong>${i?'PERSPECTIVE':'MOTION'}</strong><i>REEL LINK TO BE ADDED</i></div>`;}
$('#films').innerHTML=c.films.map((f,i)=>`<article class="film reveal">${filmMedia(f,i)}<h3>${escape(f.title)}</h3><small>${escape(f.role)} · ${escape(f.tools)}</small><p>${escape(f.caption)}</p></article>`).join('');
$('#gear-list').innerHTML=c.gear.map((g,i)=>`<li><span>0${i+1}</span>${escape(g)}</li>`).join('');
$('#socials').innerHTML=Object.entries(c.socials).map(([label,url])=>url&&safeUrl(url)?`<a href="${escape(safeUrl(url))}" target="_blank" rel="noopener">${escape(label)} ↗</a>`:`<span class="pending">${escape(label)}<small>Link to be added</small></span>`).join('');
$('#copy-email').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(c.email);$('#copy-status').textContent='Email copied.';}catch{$('#copy-status').textContent=c.email;}setTimeout(()=>$('#copy-status').textContent='',4000)});
if(!reduced){document.body.classList.add('motion-ready');const reveal=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');reveal.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>reveal.observe(e));}
// Animation libraries load independently: core navigation and content remain usable if one fails.
function initialiseLibraries(){if(window.Swiper){const slider=new Swiper('.project-slider',{slidesPerView:'auto',spaceBetween:24,grabCursor:true,speed:600,loop:false,rewind:true,pagination:{el:'.swiper-pagination',clickable:true},autoplay:reduced?false:{delay:5000,disableOnInteraction:true,pauseOnMouseEnter:true},a11y:{enabled:true}});$('.project-slider').addEventListener('focusin',()=>slider.autoplay?.stop());}if(window.anime&&!reduced){window.anime.animate('.role-line',{opacity:[0,1],translateY:[24,0],duration:900,delay:window.anime.stagger(180,{start:400}),ease:'out(3)'});}}
if(document.readyState==='complete')initialiseLibraries();else window.addEventListener('load',initialiseLibraries,{once:true});
let ticking=false;
function scrollUpdate(){ticking=false;const chapters=[...document.querySelectorAll('.chapter')];let current=0;chapters.forEach((el,i)=>{if(el.getBoundingClientRect().top<innerHeight*.65)current=i;});chapters.forEach((el,i)=>{el.classList.toggle('current',i===current);el.classList.toggle('passed',i<current)});$('#journey-count').textContent=String(current+1).padStart(2,'0');$('.timeline').style.setProperty('--progress',`${(current+.65)/chapters.length*100}%`);$('.progress-orbit').style.setProperty('--orbit',`${current*60}deg`);const transition=document.querySelector('.interlude');const tr=transition.getBoundingClientRect();if(!reduced)transition.querySelector('.interlude-orbit').style.transform='rotate('+(-30+(1-tr.top/innerHeight)*35)+'deg) scale('+(1+Math.max(0,Math.min(1,1-tr.top/innerHeight))*.4)+')';let active='';document.querySelectorAll('main section[id]').forEach(s=>{if(s.getBoundingClientRect().top<innerHeight*.4)active=s.id;});document.querySelectorAll('.nav-links a').forEach(a=>a.classList.toggle('active',a.hash==='#'+active));window.dispatchEvent(new CustomEvent('portfolio-scroll',{detail:{step:current,progress:scrollY/Math.max(1,document.documentElement.scrollHeight-innerHeight)}}));}
window.addEventListener('scroll',()=>{if(!ticking){ticking=true;requestAnimationFrame(scrollUpdate)}},{passive:true});scrollUpdate();
if(!reduced&&matchMedia('(pointer:fine)').matches){const cursor=$('.cursor');window.addEventListener('pointermove',e=>{cursor.style.opacity='1';cursor.style.transform=`translate(${e.clientX-10}px,${e.clientY-10}px)`;cursor.style.width=cursor.style.height=e.target.closest('a,button,summary')?'0px':'20px';},{passive:true});document.addEventListener('pointerleave',()=>cursor.style.opacity='0');}
// Low-memory/data-saving/reduced-motion devices keep the CSS illustrations instead of WebGL.
if(!reduced&&!navigator.connection?.saveData&&!(navigator.deviceMemory&&navigator.deviceMemory<4)){
  const load=()=>import('./scene.js').then(m=>m.mountScenes()).catch(()=>{});
  if('requestIdleCallback'in window)requestIdleCallback(load,{timeout:1800});else setTimeout(load,600);
}
